import {DndProvider} from 'react-dnd'
import {HTML5Backend} from 'react-dnd-html5-backend'
import type {EntryPointProps} from 'react-relay'
import {usePreloadedQuery} from 'react-relay'

import type {QueuePageQuery} from './__generated__/QueuePageQuery.graphql'
import type {QueueActionsBuildsQuery} from './QueueActions/__generated__/QueueActionsBuildsQuery.graphql'
import QueueBuildList from './QueueBuildList/QueueBuildList'
import {query} from './QueuePage.queries'
import QueuePageHeader from './QueuePageHeader/QueuePageHeader'

type Queries = {main: QueuePageQuery; queueActionsBuilds: QueueActionsBuildsQuery}
export default function QueuePage({queries}: EntryPointProps<Queries, {}, {}, {}>) {
  const {agentPoolRest = null} = usePreloadedQuery(query, queries.main)
  return (
    <DndProvider backend={HTML5Backend}>
      <QueuePageHeader agentPoolKey={agentPoolRest} />
      <QueueBuildList queueActionsBuildsQuery={queries.queueActionsBuilds} />
    </DndProvider>
  )
}
export type QueuePageComponent = typeof QueuePage
