import * as React from 'react'
import {Suspense, useCallback, useEffect} from 'react'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import BuildLineLayout from '../../../../containers/BuildLineLayout'
import BuildsFetcher from '../../../../containers/BuildsFetcher'
import BuildsWithLastReadyLocator from '../../../../containers/BuildsWithLastReadyLocator'
import {BuildSelectionIdProvider} from '../../../../contexts/buildSelection'
import {
  useAgentPoolIdParam,
  useBooleanQueryParam,
  useSetQueryParams,
} from '../../../../hooks/routes'
import type {NormalizedBuild} from '../../../../types'
import {stringifyId} from '../../../../types'
import Builds from '../../../common/Builds/Builds'
import type {BuildsContainerProps} from '../../../common/Builds/Builds.container'
import type {BuildCustomRendererProps} from '../../../common/Builds/Builds.types'
import Loader from '../../../common/Loader/Loader'
import BuildPager from '../../../common/Pager/BuildPager/BuildPager.container'
import ServiceMessage from '../../../common/ServiceMessage/ServiceMessage'
import type {QueueActionsBuildsQuery} from '../QueueActions/__generated__/QueueActionsBuildsQuery.graphql'
import QueueActions from '../QueueActions/QueueActions'
import QueueBuild from '../QueueBuild/QueueBuild.container'
import QueueBuildDragLayer from '../QueueBuildDragLayer/QueueBuildDragLayer.container'
import QueueFilters from '../QueueFilters/QueueFilters'
import {useBuildQueueSize} from '../QueuePage.hooks'
import {getQueuePageLocator} from '../QueuePage.utils'

import {updateQueue$} from './QueueBuildList.streams'
import {useQueueBuildDragDrop} from './useQueueBuildDragDrop'

type BuildsRendererProps = BuildsContainerProps & {
  queueActionsBuildsQuery: PreloadedQuery<QueueActionsBuildsQuery>
}
function BuildsRenderer({builds, queueActionsBuildsQuery, ...restProps}: BuildsRendererProps) {
  const setQueryParams = useSetQueryParams()
  const onlyMyPersonal = useBooleanQueryParam('onlyMyPersonal')
  const buildQueueSize = useBuildQueueSize()

  const {droppedBuildId, hoveredDropBuildId, setHoveredDropBuildId, dropBuilds, handleDrop} =
    useQueueBuildDragDrop(builds)

  const {alwaysShowLineBorders, wrapped, pathFilter} = restProps
  const renderBuild = useCallback(
    (build: NormalizedBuild, prevBuildId?: number, nextBuildId?: number) => (
      <QueueBuild
        key={stringifyId(build.id)}
        hoveredDropBuildId={hoveredDropBuildId}
        setHoveredDropBuildId={setHoveredDropBuildId}
        droppedBuildId={droppedBuildId}
        prevBuildId={prevBuildId}
        nextBuildId={nextBuildId}
        buildId={build.id}
        alwaysShowLineBorders={alwaysShowLineBorders || build.state === 'queued'}
        isQueued={build.state === 'queued'}
        wrapped={wrapped}
        pathFilter={pathFilter}
        onDrop={handleDrop}
      />
    ),
    [
      alwaysShowLineBorders,
      wrapped,
      pathFilter,
      hoveredDropBuildId,
      droppedBuildId,
      handleDrop,
      setHoveredDropBuildId,
    ],
  )

  if (builds.length === 0 && buildQueueSize !== 0 && !onlyMyPersonal && restProps.ready) {
    return (
      <ServiceMessage icon={'warning'}>
        {'You do not have permissions to see all of the items currently in the queue.'}
      </ServiceMessage>
    )
  } else {
    return (
      <>
        <QueueFilters
          onlyMyPersonal={onlyMyPersonal}
          setOnlyMyPersonal={on =>
            setQueryParams(({agentPoolId}) => ({
              agentPoolId,
              onlyMyPersonal: on ? 'true' : null,
            }))
          }
        />
        <QueueActions buildsQuery={queueActionsBuildsQuery} />
        <Suspense fallback={<Loader />}>
          <Builds builds={dropBuilds ?? builds} renderBuild={renderBuild} {...restProps} />
          <QueueBuildDragLayer wrapped={restProps.wrapped} pathFilter={restProps.pathFilter} />
        </Suspense>
      </>
    )
  }
}

type Props = {queueActionsBuildsQuery: PreloadedQuery<QueueActionsBuildsQuery>}
function QueueBuildList({queueActionsBuildsQuery}: Props) {
  const activeAgentPoolId = useAgentPoolIdParam()
  const onlyMyPersonal = useBooleanQueryParam('onlyMyPersonal')
  const locator = getQueuePageLocator(activeAgentPoolId, onlyMyPersonal)

  useEffect(() => {
    if (process.env.NODE_ENV !== 'test') {
      window.scrollTo(0, 0)
    }
  }, [locator])

  return (
    <BuildsFetcher
      withQueued
      withPager
      withBuildDetails
      withPipelineRuns
      withAnchorBuild
      updatePeriod={20000}
      customEndpoint={'/buildQueue'}
      locator={locator}
      update$={updateQueue$}
    >
      <BuildLineLayout showExactDuration={false} showComment={false}>
        <BuildSelectionIdProvider>
          <BuildsWithLastReadyLocator
            alwaysShowLineBorders
            showOverlayOnLoading
            withPager
            withLoader
            wrapped
            render={({builds, args}: BuildCustomRendererProps) => (
              <BuildsRenderer
                builds={builds}
                queueActionsBuildsQuery={queueActionsBuildsQuery}
                {...args}
              />
            )}
          />
        </BuildSelectionIdProvider>
      </BuildLineLayout>
      <BuildPager />
    </BuildsFetcher>
  )
}

export default React.memo(QueueBuildList)
