import Button from '@jetbrains/ring-ui-built/components/button/button'
import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {PlaceId} from '@jetbrains/teamcity-ui/dist/plugin'
import union from 'lodash/union'
import plur from 'plur'
import * as React from 'react'
import {memo, Suspense, useContext, useEffect, useMemo, useReducer} from 'react'
import {shallowEqual} from 'react-redux'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import {BuildSelectionIdContext} from '../../../../contexts/buildSelection'
import {useLocator} from '../../../../contexts/locator'
import {useRefetchablePreloadedQuery} from '../../../../hooks/relay/useRefetchablePreloadedQuery'
import {getBuildsData, getBuildsLocatorWithPage} from '../../../../selectors'
import {buildSelections} from '../../../../slices/buildSelections'
import type {BuildId} from '../../../../types'
import {emptyArray} from '../../../../utils/empty'
import {truthy} from '../../../../utils/guards'
import {getPoolCounters} from '../../../App/SidebarPanel/SidebarPanelContent/QueueSidebar/QueueSidebar.selectors'
import BuildBatchActions from '../../../common/Builds/BuildBatchActions/BuildBatchActions'
import {useHasAvailableActions} from '../../../common/Builds/Builds.hooks'
import {usePage} from '../../../common/Pager/Pager.hooks'
import Plugin from '../../../common/Plugin/Plugin'
import PopupMenu from '../../../common/Popup/PopupMenu'

import type {
  QueueActionsBuildsQuery,
  QueueActionsBuildsQuery$data,
} from './__generated__/QueueActionsBuildsQuery.graphql'
import {queueActionsBuildsQuery} from './QueueActions.queries'

import styles from './QueueActions.module.css'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

type ActionabilityDetectorProps = {
  buildId: BuildId
  markBuildIdAsActionable: (buildId: BuildId) => void
}
function ActionabilityDetector({buildId, markBuildIdAsActionable}: ActionabilityDetectorProps) {
  const hasAvailableActions = useHasAvailableActions(buildId)
  useEffect(() => {
    if (hasAvailableActions) {
      markBuildIdAsActionable(buildId)
    }
  }, [hasAvailableActions, markBuildIdAsActionable, buildId])
  return null
}

function QueueActionsComponent({
  queuedBuilds,
}: {
  queuedBuilds: QueueActionsBuildsQuery$data['queuedBuilds']
}) {
  const dispatch = useAppDispatch()
  const locator = useLocator() ?? ''
  const selectionId = useContext(BuildSelectionIdContext)
  const selection = useAppSelector(state => state.buildSelections[selectionId]) ?? []

  const allBuildIds = useMemo(
    () => queuedBuilds?.build?.map(build => build.id) ?? emptyArray,
    [queuedBuilds],
  )
  const [allActionableBuildIds, markBuildIdAsActionable] = useReducer(
    (state: BuildId[], action: BuildId) => (state.includes(action) ? state : [...state, action]),
    [],
  )
  const hasSelection = selection.length > 0
  const page = usePage()
  const actionableBuildIdsOnPage = useAppSelector(
    state =>
      getBuildsData(state, getBuildsLocatorWithPage(state, locator, page)).data.filter(id =>
        allActionableBuildIds.includes(id),
      ),
    shallowEqual,
  )
  // reset selector on filter change
  React.useEffect(() => {
    dispatch(buildSelections.actions.setSelection({selectionId, selection: emptyArray}))
  }, [dispatch, locator, selectionId])
  return (
    <>
      {allBuildIds.map(buildId => (
        <ActionabilityDetector
          key={buildId}
          buildId={buildId}
          markBuildIdAsActionable={markBuildIdAsActionable}
        />
      ))}
      {allActionableBuildIds.length > 1 && (
        <Dropdown anchor={<Button dropdown>{'Select'}</Button>}>
          <PopupMenu
            closeOnSelect
            data={[
              actionableBuildIdsOnPage.length > 0 &&
                actionableBuildIdsOnPage.length < allActionableBuildIds.length && {
                  label: `${actionableBuildIdsOnPage.length} ${plur(
                    'build',
                    actionableBuildIdsOnPage.length,
                  )} on this page`,
                  onClick: () =>
                    dispatch(
                      buildSelections.actions.setSelection({
                        selectionId,
                        selection: union(actionableBuildIdsOnPage, selection),
                      }),
                    ),
                },
              {
                label: `All ${allActionableBuildIds.length} ${plur(
                  'build',
                  allActionableBuildIds.length,
                )}`,
                onClick: () =>
                  dispatch(
                    buildSelections.actions.setSelection({
                      selectionId,
                      selection: allActionableBuildIds,
                    }),
                  ),
              },
            ].filter(truthy)}
          />
        </Dropdown>
      )}
      {hasSelection && (
        <span>
          {`${selection.length} selected`}
          <IconButton
            className={styles.clear}
            icon="close"
            title="Clear"
            onClick={() =>
              dispatch(buildSelections.actions.setSelection({selectionId, selection: emptyArray}))
            }
          />
        </span>
      )}
      <BuildBatchActions />
      <Plugin className={styles.plugins} placeId={PlaceId.SAKURA_QUEUE_ACTIONS} />
    </>
  )
}

type Props = {buildsQuery: PreloadedQuery<QueueActionsBuildsQuery>}

const QueueActionsContainer = memo(function QueueActionsContainerComponent(props: Props) {
  const [{queuedBuilds}, fetchAllBuilds] = useRefetchablePreloadedQuery(
    queueActionsBuildsQuery,
    props.buildsQuery,
  )
  const locator = useLocator() ?? ''
  const poolCounters = useAppSelector(getPoolCounters)

  React.useEffect(() => {
    if (!IS_STORYBOOK) {
      fetchAllBuilds({locator: `${locator},count:10000,lookupLimit:10000`})
    }
  }, [poolCounters, locator, fetchAllBuilds])

  return <QueueActionsComponent queuedBuilds={queuedBuilds} />
})

function QueueActions(props: Props) {
  return (
    <div className={styles.actions}>
      <Suspense>
        <QueueActionsContainer {...props} />
      </Suspense>
    </div>
  )
}

export default QueueActions
