import * as React from 'react'

import {useFetchEffect} from '../../../hocs/withEffect'
import {subscribeonStatisticsUpdates} from '../../../utils/subscriber'
import type {StatisticsUpdateData} from '../../App/Header/Links/Links.types'

export function useBuildQueueSize() {
  const [statistics, setStatistics] = React.useState<StatisticsUpdateData | null | undefined>(null)
  const {buildQueueSize = 0} = statistics ?? {}
  useFetchEffect(
    () =>
      subscribeonStatisticsUpdates((data: StatisticsUpdateData | null | undefined) =>
        setStatistics(data),
      ),
    [],
  )
  return buildQueueSize
}
