import plur from 'plur'
import {memo} from 'react'
import {graphql, useFragment} from 'react-relay'

import {useAppSelector} from '../../../../hooks/react-redux'
import useDocumentTitle from '../../../../hooks/useDocumentTitle'
import {getPoolCounters} from '../../../App/SidebarPanel/SidebarPanelContent/QueueSidebar/QueueSidebar.selectors'
import PageTitle from '../../../common/PageTitle/PageTitle'
import {useBuildQueueSize} from '../QueuePage.hooks'

import type {QueuePageHeader_agentPool$key} from './__generated__/QueuePageHeader_agentPool.graphql'

import styles from './QueuePageHeader.module.css'

const agentPoolFragment = graphql`
  fragment QueuePageHeader_agentPool on AgentPoolRest {
    id
    name
  }
`

type Props = {
  agentPoolKey: QueuePageHeader_agentPool$key | null
}

function QueuePageHeader({agentPoolKey}: Props) {
  const {id, name} = useFragment(agentPoolFragment, agentPoolKey) ?? {}
  const buildQueueSize = useBuildQueueSize()
  const poolCounters = useAppSelector(getPoolCounters)
  const count = id != null ? (poolCounters[id]?.total ?? 0) : buildQueueSize
  let title = `${count ? `${count} ${plur('build', count)}` : 'Builds'} in queue`

  if (name != null) {
    title += ` in ${name} pool`
  }

  useDocumentTitle(`${title} — TeamCity`)
  return <PageTitle className={styles.header}>{title}</PageTitle>
}

export default memo(QueuePageHeader)
